import chess, chess.pgn, io, json, re, random

EXAMPLE = "rnb1k1nr/p2p1ppp/3B4/1p1NPN1P/6P1/3P1Q2/P1P5/q4Kb1 w kq - 0 1"
PGN_OPERA = "1. e4 e5 2. Nf3 d6 3. d4 Bg4 4. dxe5 Bxf3 5. Qxf3 dxe5 6. Bc4 Nf6 7. Qb3 Qe7 8. Nc3 c6 9. Bg5 b5 10. Nxb5 cxb5 11. Bxb5+ Nbd7 12. O-O-O Rd8 13. Rxd7 Rxd7 14. Rd1 Qe6 15. Bxd7+ Nxd7 16. Qb8+ Nxb8 17. Rd8# 1-0"

def target_fens(fen):
    b = chess.Board(fen)
    seen = {}
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN:
            continue
        b2 = b.copy(); b2.push(m)
        seen[b2.fen()] = None
    return list(seen.keys())

def opera_positions():
    game = chess.pgn.read_game(io.StringIO(PGN_OPERA))
    board = game.board()
    pos = [board.fen()]
    b = board.copy(); mc = 0
    for move in game.mainline_moves():
        mc += 1
        if mc % 2 == 1:
            pos.append(b.fen())
        b.push(move)
    return pos

def random_white_positions(rng, count_games, max_plies=60):
    pos = []
    for _ in range(count_games):
        b = chess.Board()
        for ply in range(max_plies):
            if b.is_game_over():
                break
            if b.turn == chess.WHITE:
                pos.append(b.fen())
            try:
                b.push(rng.choice(list(b.legal_moves)))
            except Exception:
                break
    return pos

def main():
    rng = random.Random(12345)
    pool = [chess.Board().fen()] + opera_positions() + [EXAMPLE]
    pool += random_white_positions(rng, 60)
    rules = []; seen = set()
    for fen in pool:
        try:
            first4 = " ".join(fen.split(" ")[:4])
        except Exception:
            continue
        if " w " not in fen:
            continue
        if first4 in seen:
            continue
        seen.add(first4)
        tfs = target_fens(fen)
        pat = "^" + re.escape(first4) + r"(?: .*)?$"
        repl = "\n".join(tfs)
        rules.append([pat, repl])
    data = json.dumps(rules)
    if len(data) > 9*1024*1024:
        print("TOO LARGE", len(data)); return
    open("/app/re.json","w").write(data)
    print("positions:", len(rules), "bytes:", len(data))

if __name__ == "__main__":
    main()
