def sample_positions(rng, k):
    pos = []
    for _ in range(80):
        b = chess.Board()
        for ply in range(50):
            if b.is_game_over(): break
            if b.turn == chess.WHITE: pos.append(b.fen())
            try: b.push(rng.choice(list(b.legal_moves)))
            except Exception: break
    seen = list(dict.fromkeys(pos)); rng.shuffle(seen); return seen[:k]

